create policy "reference institutions read" on public.institutions for select to authenticated using(true);
create policy "interests read" on public.interests for select to authenticated using(true);
create policy "roles read" on public.roles for select to authenticated using(true);
create policy "profiles authenticated read" on public.profiles for select to authenticated using(id=auth.uid() or onboarding_complete);
create policy "profiles own update" on public.profiles for update to authenticated using(id=auth.uid()) with check(id=auth.uid());
create policy "profiles own insert" on public.profiles for insert to authenticated with check(id=auth.uid());
create policy "user interests own" on public.user_interests for all to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy "user roles own read" on public.user_roles for select to authenticated using(user_id=auth.uid() or public.has_role('admin') or public.has_role('super_admin'));
create policy "channels active read" on public.channels for select to authenticated using(is_active or public.is_staff());
create policy "channels admin manage" on public.channels for all to authenticated using(public.has_role('admin') or public.has_role('super_admin')) with check(public.has_role('admin') or public.has_role('super_admin'));
create policy "active posts read" on public.posts for select to authenticated using((status='active' and deleted_at is null) or author_id=auth.uid() or public.is_staff());
create policy "verified users create posts" on public.posts for insert to authenticated with check(author_id=auth.uid() and exists(select 1 from auth.users u where u.id=auth.uid() and u.email_confirmed_at is not null) and exists(select 1 from public.channels c where c.id=channel_id and c.is_active));
create policy "authors manage posts" on public.posts for update to authenticated using(author_id=auth.uid() and status='active') with check(author_id=auth.uid());
create policy "post media follows owner" on public.post_media for all to authenticated using(exists(select 1 from public.posts p where p.id=post_id and (p.author_id=auth.uid() or public.is_staff()))) with check(exists(select 1 from public.posts p where p.id=post_id and p.author_id=auth.uid()));
create policy "active comments read" on public.comments for select to authenticated using((status='active' and deleted_at is null) or author_id=auth.uid() or public.is_staff());
create policy "verified users comment" on public.comments for insert to authenticated with check(author_id=auth.uid() and exists(select 1 from auth.users u where u.id=auth.uid() and u.email_confirmed_at is not null));
create policy "authors manage comments" on public.comments for update to authenticated using(author_id=auth.uid() and status='active') with check(author_id=auth.uid());
create policy "own reactions" on public.reactions for all to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy "published resources read" on public.resources for select to authenticated using(status='published' or created_by=auth.uid() or public.has_role('content_creator') or public.has_role('admin') or public.has_role('super_admin'));
create policy "content staff resources" on public.resources for all to authenticated using(public.has_role('content_creator') or public.has_role('admin') or public.has_role('super_admin')) with check(public.has_role('content_creator') or public.has_role('admin') or public.has_role('super_admin'));
create policy "resource categories read" on public.resource_categories for select to authenticated using(true);
create policy "resource tags read" on public.resource_tags for select to authenticated using(true);
create policy "resource tag links read" on public.resource_tag_links for select to authenticated using(true);
create policy "own bookmarks" on public.bookmarks for all to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy "record own resource views" on public.resource_views for insert to authenticated with check(user_id=auth.uid());
create policy "own resource views read" on public.resource_views for select to authenticated using(user_id=auth.uid() or public.has_role('admin'));
create policy "published events read" on public.events for select to authenticated using(status='published' or public.has_role('programme_manager') or public.has_role('admin') or public.has_role('super_admin'));
create policy "programme staff events" on public.events for all to authenticated using(public.has_role('programme_manager') or public.has_role('admin') or public.has_role('super_admin')) with check(public.has_role('programme_manager') or public.has_role('admin') or public.has_role('super_admin'));
create policy "own rsvps" on public.event_rsvps for all to authenticated using(user_id=auth.uid() or public.has_role('programme_manager')) with check(user_id=auth.uid() or public.has_role('programme_manager'));
create policy "published opportunities read" on public.opportunities for select to authenticated using(status='published' or public.has_role('content_creator') or public.has_role('admin') or public.has_role('super_admin'));
create policy "content staff opportunities" on public.opportunities for all to authenticated using(public.has_role('content_creator') or public.has_role('admin') or public.has_role('super_admin')) with check(public.has_role('content_creator') or public.has_role('admin') or public.has_role('super_admin'));
create policy "opportunity categories read" on public.opportunity_categories for select to authenticated using(true);
create policy "own opportunity bookmarks" on public.opportunity_bookmarks for all to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy "create own reports" on public.content_reports for insert to authenticated with check(reporter_id=auth.uid());
create policy "reports own or moderators" on public.content_reports for select to authenticated using(reporter_id=auth.uid() or public.is_staff());
create policy "moderators update reports" on public.content_reports for update to authenticated using(public.is_staff()) with check(public.is_staff());
create policy "moderation actions staff" on public.moderation_actions for all to authenticated using(public.is_staff()) with check(public.is_staff());
create policy "own notifications" on public.notifications for select to authenticated using(user_id=auth.uid());
create policy "mark own notifications" on public.notifications for update to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy "own notification preferences" on public.notification_preferences for all to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy "own push tokens" on public.push_tokens for all to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy "admin audit read" on public.audit_logs for select to authenticated using(public.has_role('admin') or public.has_role('super_admin'));
create policy "settings read" on public.app_settings for select to authenticated using(true);
create policy "settings admin manage" on public.app_settings for all to authenticated using(public.has_role('admin') or public.has_role('super_admin')) with check(public.has_role('admin') or public.has_role('super_admin'));

